/* rocklabel dashboard — seven views, the run drawer, the runs board, job streaming.
 *
 * One page, no build step, no network dependency. The server is the source of
 * truth for both the command catalog and the command line a form produces, so
 * the preview you see in the drawer footer is generated by the same code that
 * builds the argv — it cannot drift.
 *
 * The views: PIPELINE is the main loop and its commands; RUNS is the training
 * board (/api/board); TRAINING is whatever sweep is on the GPU right now,
 * fold by fold; DATA is recordings/labels/datasets; JOBS is history plus a live
 * log; LIVE is sensor state and whatever viewer is running; TOOLS is everything
 * that is not the main loop.
 */
'use strict';

const S = {
  catalog: null,
  inv: null,
  machine: null,
  jobs: [],
  activeJob: null,
  jobCursor: 0,
  follow: true,
  view: 'pipeline',
  stageFilter: 'all',
  search: '',
  dataTab: 'recordings',
  drawerCmd: null,
  openRows: new Set(),
  showAllHelp: false,
  invSig: null,
  board: null,          // {rows, suites} from /api/board — expensive, so cached
  boardSig: null,       // inventory signature the board was loaded under
  boardSuite: 'all',    // which sweep is expanded ('all' = every suite)
  boardLoading: false,
  noteEditing: null,    // row key whose note editor is open
};

/* ------------------------------------------------------------------ utils */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

function h(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

function fmtBytes(n) {
  if (!n) return '0 B';
  const u = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.min(u.length - 1, Math.floor(Math.log(n) / Math.log(1024)));
  const v = n / Math.pow(1024, i);
  return `${v >= 100 || i === 0 ? Math.round(v) : v.toFixed(1)} ${u[i]}`;
}
function fmtNum(n) {
  if (n == null) return '—';
  if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M`;
  if (n >= 1e4) return `${(n / 1e3).toFixed(0)}K`;
  return n.toLocaleString();
}
function fmtAgo(ts) {
  if (!ts) return '—';
  const s = Date.now() / 1000 - ts;
  if (s < 60) return 'just now';
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  const d = Math.floor(s / 86400);
  if (d < 30) return `${d}d ago`;
  return new Date(ts * 1000).toLocaleDateString();
}
function fmtDur(s) {
  if (s == null) return '—';
  if (s < 60) return `${s.toFixed(0)}s`;
  const m = Math.floor(s / 60);
  return `${m}m ${Math.round(s - m * 60)}s`;
}
/** One fixed-width score. Null-safe because half the board's folds are missing. */
function fmtScore(n) {
  return n == null ? '—' : n.toFixed(3);
}

async function api(path, opts) {
  const res = await fetch(path, opts);
  const body = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(body.error || `${res.status} ${res.statusText}`);
  return body;
}
async function post(path, data) {
  return api(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data || {}),
  });
}

function toast(msg, kind, action) {
  const box = $('#toasts');
  const t = h('div', `toast${kind === 'err' ? ' err' : ''}`);
  t.appendChild(h('span', null, msg));
  if (action) {
    const b = h('button', null, action.label);
    b.onclick = () => { action.fn(); t.remove(); };
    t.appendChild(b);
  }
  box.appendChild(t);
  setTimeout(() => t.remove(), action ? 8000 : 4200);
}

/* ---------------------------------------------------------------- routing */
function setView(name) {
  S.view = name;
  $$('.nav-item').forEach((b) => b.classList.toggle('is-active', b.dataset.view === name));
  $$('.view').forEach((v) => v.classList.toggle('is-active', v.id === `view-${name}`));
  window.scrollTo({ top: 0, behavior: 'instant' });
  render();
}

/* =============================================================== PIPELINE */
function renderPipeline() {
  const t = S.inv.totals;

  // ---- hero: the one number the project is chasing
  const f1 = t.best_f1;
  $('#heroF1').textContent = f1 ? f1.toFixed(3) : '—';
  $('#heroF1Sub').textContent = f1
    ? `best held-out F1 · ${t.best_run} · ${t.runs} sweep folds evaluated`
    : 'no completed training runs yet';
  $('#heroF1Meter').style.width = `${Math.round((f1 || 0) * 100)}%`;

  // ---- tiles: where the project stands, click through to each stage
  const tiles = [
    { label: 'Recordings', value: String(t.recordings), sub: `${fmtBytes(t.recordings_bytes)} · ${t.recordings_labeled} labeled`, view: 'data', tab: 'recordings' },
    { label: 'Rocks labeled', value: String(t.rocks), sub: `across ${t.labels} label files`, view: 'data', tab: 'labels' },
    { label: 'Training samples', value: fmtNum(t.samples), sub: `${fmtNum(t.rock_samples)} rock · ${t.datasets} datasets`, view: 'data', tab: 'datasets' },
    { label: 'Training folds', value: String(t.runs), sub: 'sweep folds evaluated', view: 'runs' },
  ];
  const box = $('#tiles');
  box.innerHTML = '';
  tiles.forEach((tile) => {
    const b = h('button', 'tile');
    b.appendChild(h('div', 'stat-label', tile.label));
    b.appendChild(h('div', 'stat-value', tile.value));
    b.appendChild(h('div', 'stat-sub', tile.sub));
    b.onclick = () => { if (tile.tab) S.dataTab = tile.tab; setView(tile.view); };
    box.appendChild(b);
  });

  // ---- flow: the loop with this project's counts at each step
  const counts = {
    capture: { n: t.recordings, unit: t.recordings === 1 ? 'recording' : 'recordings' },
    triage: { n: t.recordings, unit: 'to inspect / trim' },
    slam: { n: t.recordings, unit: 'runs to solve poses for' },
    label: { n: t.rocks, unit: t.rocks === 1 ? 'rock labeled' : 'rocks labeled' },
    dataset: { n: t.samples, unit: 'samples generated' },
    train: { n: t.runs_complete, unit: 'folds evaluated' },
    deploy: { n: S.inv.checkpoints.filter((c) => c.name.endsWith('best.pt')).length, unit: 'checkpoints ready' },
  };
  const flow = $('#flow');
  flow.innerHTML = '';
  S.catalog.stages.forEach((st) => {
    const c = counts[st.id] || { n: 0, unit: '' };
    const b = h('button', 'flow-stage');
    b.dataset.filled = c.n > 0 ? '1' : '0';
    const title = h('div', 'flow-title');
    title.appendChild(h('span', 'flow-dot'));
    title.appendChild(document.createTextNode(st.title));
    b.appendChild(title);
    b.appendChild(h('div', 'flow-count', fmtNum(c.n)));
    b.appendChild(h('div', 'flow-blurb', c.unit || st.blurb));
    b.title = st.blurb;
    b.onclick = () => { S.stageFilter = st.id; setView('tools'); };
    flow.appendChild(b);
  });

  // ---- the pipeline's own commands, grouped by stage in loop order
  renderCommandGroups($('#pipelineGroups'), pipelineCommands(), true);

  // ---- quick actions
  const qbox = $('#quickActions');
  qbox.innerHTML = '';
  [['live', 'Open the live view', 'Watch the sensor, with or without a model.'],
   ['record', 'Record a run', 'Capture straight to an .mcap.'],
   ['label', 'Label a recording', 'Place rock labels on the fused cloud.'],
   ['generate', 'Generate a dataset', 'Turn labels into training data.'],
  ].forEach(([id, title, desc]) => qbox.appendChild(quickButton(id, title, desc)));

  // ---- recent activity
  const items = [];
  S.inv.recordings.slice(0, 5).forEach((r) => items.push({ kind: 'recording', name: r.name, ts: r.mtime }));
  S.inv.labels.slice(0, 5).forEach((l) => items.push({ kind: 'labels', name: `${l.name} · ${l.rock_count} rocks`, ts: l.mtime }));
  S.inv.datasets.forEach((d) => items.push({ kind: 'dataset', name: d.name, ts: d.mtime }));
  items.sort((a, b) => b.ts - a.ts);
  const list = $('#activity');
  list.innerHTML = '';
  if (!items.length) list.appendChild(h('li', 'muted', 'Nothing here yet — start with a recording.'));
  items.slice(0, 9).forEach((it) => {
    const li = h('li');
    li.appendChild(h('span', 'act-kind', it.kind));
    li.appendChild(h('span', 'act-name', it.name));
    li.appendChild(h('span', 'act-when', fmtAgo(it.ts)));
    list.appendChild(li);
  });
}

function quickButton(cmdId, title, desc, prefill) {
  const cmd = S.catalog.commands.find((c) => c.id === cmdId);
  const b = h('button', 'quick-btn');
  b.appendChild(h('div', 'quick-icon', cmd ? cmd.icon : '▸'));
  const txt = h('div');
  txt.appendChild(h('div', 'quick-title', title));
  txt.appendChild(h('div', 'quick-desc', desc));
  b.appendChild(txt);
  b.onclick = () => openDrawer(cmdId, prefill);
  return b;
}

/* ====================================================== COMMAND GROUPINGS */
/** The ten main-loop commands, in workflow order. */
function pipelineCommands() {
  return S.catalog.commands.filter((c) => c.tier !== 'tool');
}
/** The specialist rest. */
function toolCommands() {
  return S.catalog.commands.filter((c) => c.tier === 'tool');
}

/** Group `cmds` by stage into `wrap`. With headings, unless `quiet` (the
 *  pipeline view already says which stage it is). */
function renderCommandGroups(wrap, cmds, quiet) {
  wrap.innerHTML = '';
  const q = S.search.toLowerCase();
  const matches = (c) => (S.stageFilter === 'all' || c.stage === S.stageFilter)
    && (!q || `${c.title} ${c.cli} ${c.tagline} ${c.what}`.toLowerCase().includes(q));

  let shown = 0;
  S.catalog.stages.forEach((stage) => {
    const here = cmds.filter((c) => c.stage === stage.id && matches(c));
    if (!here.length) return;
    shown += here.length;
    const group = h('section', 'cmd-group');
    if (!quiet || S.stageFilter !== 'all') {
      const head = h('div', 'cmd-group-head');
      head.appendChild(h('h2', null, stage.title));
      head.appendChild(h('span', null, stage.blurb));
      group.appendChild(head);
    }
    const grid = h('div', 'cmd-grid');
    here.forEach((c) => grid.appendChild(commandCard(c)));
    group.appendChild(grid);
    wrap.appendChild(group);
  });
  if (!shown) {
    const empty = h('div', 'empty');
    empty.appendChild(h('strong', null, 'No commands match'));
    empty.appendChild(h('div', null, 'Try a different search or clear the stage filter.'));
    wrap.appendChild(empty);
  }
}

function renderTools() {
  // The search box and chips are static HTML; wire them once.
  if (!$('#cmdSearch').dataset.wired) {
    $('#cmdSearch').dataset.wired = '1';
    $('#cmdSearch').addEventListener('input', (e) => {
      S.search = e.target.value;
      renderTools();
    });
  }
  const chips = $('#stageChips');
  if (!chips.dataset.built) {
    [{ id: 'all', title: 'All' }, ...S.catalog.stages].forEach((st) => {
      const c = h('button', 'chip', st.title);
      c.dataset.stage = st.id;
      c.onclick = () => { S.stageFilter = st.id; renderTools(); };
      chips.appendChild(c);
    });
    chips.dataset.built = '1';
  }
  $$('.chip', chips).forEach((c) => c.classList.toggle('is-active', c.dataset.stage === S.stageFilter));
  renderCommandGroups($('#commandGroups'), toolCommands(), false);
}

function commandCard(c) {
  const card = h('button', 'cmd-card');
  const top = h('div', 'cmd-card-top');
  top.appendChild(h('div', 'cmd-icon', c.icon));
  const names = h('div');
  names.appendChild(h('div', 'cmd-name', c.title));
  names.appendChild(h('div', 'cmd-cli', c.cli));
  top.appendChild(names);
  card.appendChild(top);
  card.appendChild(h('div', 'cmd-tagline', c.tagline));
  const flags = h('div', 'cmd-flags');
  if (c.gui) flags.appendChild(h('span', 'flag gui', 'opens a window'));
  if (c.long_running) flags.appendChild(h('span', 'flag slow', 'long running'));
  const n = c.params.filter((p) => !p.advanced).length;
  flags.appendChild(h('span', 'flag', `${n} option${n === 1 ? '' : 's'}`));
  card.appendChild(flags);
  card.onclick = () => openDrawer(c.id);
  return card;
}

/* =================================================================== RUNS */
/** Load the board if it has never been loaded, or if the project changed since
 *  it was. Reads every fold directory on disk, so it stays off the 5 s poll —
 *  the Refresh button and entry-with-changes are what re-reads it. */
function ensureBoard() {
  if (!S.board && !S.boardLoading) loadBoard();
}

async function loadBoard() {
  S.boardLoading = true;
  try {
    S.board = await api('/api/board');
    S.boardSig = S.invSig;
  } catch (e) {
    toast(`Could not read the runs board: ${e.message}`, 'err');
  } finally {
    S.boardLoading = false;
    if (S.view === 'runs') renderBoard();
  }
}

/** Suites in display order: the one with the freshest folds first, ties and
 *  never-touched suites by name so the order is stable across renders. */
function orderedSuites() {
  return [...((S.board && S.board.suites) || [])].sort((a, b) =>
    (b.last_activity || 0) - (a.last_activity || 0) ||
    String(a.name).localeCompare(String(b.name)));
}

function renderBoard() {
  const chips = $('#suiteChips');
  chips.innerHTML = '';
  const suites = orderedSuites();
  ['All', ...suites].forEach((su, i) => {
    const name = i === 0 ? 'all' : su.name;
    const c = h('button', `chip${S.boardSuite === name ? ' is-active' : ''}`,
      i === 0 ? 'All' : su.title);
    c.dataset.suite = name;
    c.onclick = () => { S.boardSuite = name; renderBoard(); };
    chips.appendChild(c);
  });
  $('#boardRefresh').onclick = () => loadBoard();

  const body = $('#boardBody');
  body.innerHTML = '';
  if (!S.board) {
    body.appendChild(h('div', 'muted', S.boardLoading
      ? 'reading every fold from disk…' : 'board unavailable.'));
    return;
  }

  // Suites lead with the work that is current, not the alphabet; ties and
  // never-touched suites fall back to their name so the order is stable.
  let shown = S.boardSuite === 'all' ? orderedSuites()
    : orderedSuites().filter((su) => su.name === S.boardSuite);
  if (!shown.length) shown = suites;
  if (!shown.length) {
    const e = h('div', 'empty');
    e.appendChild(h('strong', null, 'No training runs yet'));
    e.appendChild(h('div', null, 'Build a cache, then run Train or Ablation sweep — finished '
      + 'settings show up here ranked, with their notes.'));
    const q = h('div', 'quick');
    q.style.marginTop = '16px';
    q.appendChild(quickButton('train-cache', 'Build cache', 'Pool datasets for training.'));
    q.appendChild(quickButton('train-train', 'Train one fold', 'One setting, one held-out run.'));
    q.appendChild(quickButton('train-ablate', 'Ablation sweep', 'The full matrix, overnight.'));
    body.appendChild(e);
    body.appendChild(q);
    return;
  }

  shown.forEach((suite) => {
    const rows = S.board.rows.filter((r) => r.suite === suite.name);
    body.appendChild(boardSuiteCard(suite, rows));
  });
}

/* One sweep's section: header, the contrasts already measured, the per-fold
 * chart, then every arm ranked best first. */
function boardSuiteCard(suite, rows) {
  const sec = h('section', 'board-suite');

  const head = h('div', 'board-suite-head');
  head.appendChild(h('h2', null, suite.title));
  const meta = [`${suite.arms} setting${suite.arms === 1 ? '' : 's'}`];
  if (suite.folds) meta.push(`${suite.folds} folds`);
  if (suite.noise_floor != null) meta.push(`noise floor ±${suite.noise_floor.toFixed(3)}`);
  head.appendChild(h('span', 'board-suite-meta', meta.join(' · ')));
  sec.appendChild(head);
  if (suite.blurb) sec.appendChild(h('p', 'board-suite-blurb', suite.blurb));

  // Contrasts: the paired comparisons the report already ran, phrased as the
  // question they answer. Delta sign follows variant minus baseline.
  (suite.contrasts || []).forEach((c) => {
    if (!c.metric || c.metric.mean_delta == null) return;
    const line = h('div', 'contrast-line');
    const d = c.metric.mean_delta;
    const cls = Math.abs(d) < 1e-9 ? 'flat' : d > 0 ? 'pos' : 'neg';
    line.appendChild(h('span', 'contrast-delta ' + cls,
      `${d > 0 ? '+' : ''}${d.toFixed(3)}`));
    line.appendChild(h('span', null,
      `${c.variant} vs ${c.baseline} over ${c.n_folds} folds`
      + (c.metric.p_value != null ? ` (p=${c.metric.p_value.toFixed(3)})` : '')
      + (c.using_norm ? ', rock-share-normalized' : '')
      + ` — ${c.question}`));
    sec.appendChild(line);
  });

  // Per-fold columns, one series per arm, so shape differences across folds
  // are visible at a glance. Missing folds are NaN — the chart draws gaps.
  const scored = rows.filter((r) => r.per_fold.some((f) => f.pr_auc != null));
  if (scored.length > 1) {
    const folds = [...new Set(scored.flatMap((r) => r.per_fold.map((f) => f.fold)))].sort();
    sec.appendChild(window.Charts.groupedColumns({
      categories: folds,
      series: scored.map((r) => ({
        name: r.label,
        values: folds.map((f) => {
          const pf = r.per_fold.find((x) => x.fold === f);
          return pf ? (pf.norm_pr_auc != null ? pf.norm_pr_auc : pf.pr_auc) : NaN;
        }),
      })),
      max: 1,
      caption: `${suite.title}: per-fold scores, rock-share-normalized where the fold's rock share is known.`,
    }));
  }

  const tbl = h('table');
  const thead = h('thead');
  const hr = h('tr');
  // Column order matches boardRow's cells exactly.
  ['#', 'Setting', 'Score', '', 'Folds', 'Range', 'Note', ''].forEach((label, i) => {
    hr.appendChild(h('th', i === 4 || i === 5 ? 'num' : '', label));
  });
  thead.appendChild(hr);
  tbl.appendChild(thead);
  const tbody = h('tbody');
  rows.forEach((row, i) => {
    const [trMain, detail] = boardRow(row, i);
    tbody.appendChild(trMain);
    tbody.appendChild(detail);
  });
  tbl.appendChild(tbody);

  const wrap = h('div', 'table-wrap');
  wrap.appendChild(tbl);
  sec.appendChild(wrap);
  return sec;
}

/** One arm row plus its detail line, returned as [mainTr, detailTr] for the
 *  tbody. The whole main row toggles the detail; the note button must not.
 *  The detail is built eagerly (it is cheap, all numbers are already in hand)
 *  and the note editor is appended whenever this row is the one being edited —
 *  opening or closing an editor re-renders the board, so no lazy filling is
 *  needed here. Keys go through S.openRows so expansion survives the poll's
 *  re-render, same as the Data tables. */
function boardRow(row, index) {
  const trMain = h('tr', 'board-row board-row-main');
  const detail = h('tr', 'row-detail');
  const td = h('td');
  td.colSpan = 99;
  const inner = h('div', 'row-detail-inner');
  td.appendChild(inner);
  detail.appendChild(td);

  const key = `board:${row.key}`;
  const caret = h('button', 'expander', '▸');
  caret.setAttribute('aria-label', `Details for ${row.label}`);
  const apply = (open) => {
    detail.hidden = !open;
    trMain.classList.toggle('is-open', open);
    caret.textContent = open ? '▾' : '▸';
    if (open) S.openRows.add(key);
    else S.openRows.delete(key);
  };

  // -- rank
  trMain.appendChild(h('td', 'board-rank', String(index + 1)));
  // -- arm identity
  const armTd = h('td', 'board-arm');
  const nameEl = h('div', 'board-arm-name', row.label);
  nameEl.appendChild(h('span', `kind-badge ${row.kind === 'segmenter' ? 'seg' : 'cls'}`,
    row.kind === 'segmenter' ? 'SEG' : 'CLS'));
  armTd.appendChild(nameEl);
  armTd.appendChild(h('div', 'board-arm-sub', (row.features || []).join(' ')));
  trMain.appendChild(armTd);
  // -- score: normalized when the fold populations allow it, raw otherwise
  const useNorm = row.norm_pr_auc != null;
  const scoreVal = useNorm ? row.norm_pr_auc : row.pr_auc;
  const scoreTd = h('td', 'board-score');
  const num = h('div', `board-score-num${index === 0 ? ' best' : ''}`, fmtScore(scoreVal));
  num.title = useNorm
    ? 'Rock-share-normalized mean: guessing scores 0, perfect scores 1.'
    : 'Mean PR-AUC across finished folds.';
  scoreTd.appendChild(num);
  scoreTd.appendChild(h('div', 'board-score-lbl', useNorm ? 'normalized' : 'PR-AUC'));
  const bar = h('div', 'bar');
  const barFill = h('div', 'bar-fill');
  barFill.style.width = `${Math.max(0, Math.min(1, scoreVal || 0)) * 100}%`;
  bar.appendChild(barFill);
  scoreTd.appendChild(bar);
  trMain.appendChild(scoreTd);
  // -- spacer column matching the header's ''
  trMain.appendChild(h('td'));
  // -- folds done
  const foldsTd = h('td', 'board-folds');
  foldsTd.appendChild(h('span', 'done', String(row.folds_done)));
  foldsTd.appendChild(document.createTextNode(
    `/${row.folds_total || '?'}` + (row.reported ? ' ✓' : '')));
  trMain.appendChild(foldsTd);
  // -- best…worst spread
  const rangeTd = h('td', 'board-range');
  rangeTd.textContent = row.best_fold_pr_auc != null
    ? `${fmtScore(row.best_fold_pr_auc)} … ${fmtScore(row.worst_fold_pr_auc)}`
    : '—';
  rangeTd.title = row.best_fold
    ? `best ${row.best_fold}, worst ${row.worst_fold}` : '';
  trMain.appendChild(rangeTd);
  // -- note: seeded conclusions italic until typed over
  const noteTd = h('td', 'board-note' + (row.note_source === 'seed' ? ' seed' : ''));
  const noteWrap = h('div', 'note-text', row.note || '');
  noteWrap.title = row.note_source === 'seed'
    ? 'Measured conclusion from the sweep report — edit to override.' : '';
  noteTd.appendChild(noteWrap);
  const editBtn = h('button', 'note-edit-btn', row.note ? 'edit' : '+ note');
  editBtn.onclick = (e) => {
    e.stopPropagation();
    S.noteEditing = S.noteEditing === row.key ? null : row.key;
    renderBoard();
  };
  noteTd.appendChild(editBtn);
  trMain.appendChild(noteTd);
  // -- caret
  const caretTd = h('td');
  caretTd.appendChild(caret);
  trMain.appendChild(caretTd);

  caretTd.onclick = (e) => { e.stopPropagation(); apply(detail.hidden); };
  trMain.onclick = () => apply(detail.hidden);

  fillDetail(inner, row);
  if (S.noteEditing === row.key) inner.appendChild(noteEditor(row));
  apply(S.openRows.has(key));

  return [trMain, detail];
}

/* The note editor: textarea prefilled with the current text (seed text too —
 * editing a conclusion should start from the conclusion), Save persists, Clear
 * drops the override and falls back to the seed. */
function noteEditor(row) {
  const box = h('div', 'note-editor');
  box.onclick = (e) => e.stopPropagation();
  box.appendChild(h('div', 'note-source', `note · ${row.key}`));
  const ta = h('textarea', 'input');
  ta.value = row.note || '';
  ta.rows = 3;
  ta.placeholder = 'What did this setting teach you?';
  ta.onkeydown = (e) => e.stopPropagation();
  box.appendChild(ta);
  const acts = h('div', 'chip-row');
  const save = h('button', 'btn btn-sm btn-primary', 'Save note');
  save.onclick = async (e) => {
    e.stopPropagation();
    save.disabled = true;
    try {
      const r = await api('/api/board/notes', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ key: row.key, note: ta.value }),
      });
      row.note = r.note;
      row.note_source = r.source || 'custom';
      S.noteEditing = null;
      renderBoard();
      toast(r.note ? 'Note saved.' : 'Note cleared.');
    } catch (err) {
      toast(err.message, 'err');
      save.disabled = false;
    }
  };
  acts.appendChild(save);
  if (row.note_source === 'custom') {
    acts.appendChild(button('btn btn-sm btn-ghost', 'Revert to seeded conclusion', async (ev) => {
      ev.stopPropagation();
      try {
        const r = await api('/api/board/notes', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ key: row.key, note: '' }),
        });
        row.note = r.note;
        row.note_source = r.source || 'seed';
        S.noteEditing = null;
        renderBoard();
      } catch (err) { toast(err.message, 'err'); }
    }));
  }
  acts.appendChild(button('btn btn-sm btn-ghost', 'Cancel', (ev) => {
    ev.stopPropagation();
    S.noteEditing = null;
    renderBoard();
  }));
  box.appendChild(acts);
  return box;
}

/** The detail under an arm row: settings, per-fold chips. */
function fillDetail(inner, row) {
  const grid = h('div', 'detail-grid');
  grid.appendChild(detailItem('Model', row.model || '—'));
  grid.appendChild(detailItem('Channels', (row.features || []).join(' ') || '—'));
  const ov = Object.entries(row.overrides || {});
  grid.appendChild(detailItem('Overrides', ov.length
    ? ov.map(([k, v]) => `${k}=${v}`).join(', ') : 'none'));
  grid.appendChild(detailItem('Seed', row.seed == null ? 'default' : String(row.seed)));
  grid.appendChild(detailItem('Last activity', fmtAgo(row.last_activity)));
  if (row.best_fold) {
    grid.appendChild(detailItem('Best / worst fold',
      `${row.best_fold} (${fmtScore(row.best_fold_pr_auc)}) / `
      + `${row.worst_fold} (${fmtScore(row.worst_fold_pr_auc)})`));
  }
  inner.appendChild(grid);

  const chips = h('div', 'board-fold-chips');
  row.per_fold.forEach((f) => {
    const c = h('span', `fold-chip${f.pr_auc == null ? ' missing' : ''}`);
    c.appendChild(document.createTextNode(`${f.fold} `));
    c.appendChild(h('b', null, fmtScore(f.pr_auc)));
    if (f.norm_pr_auc != null) c.appendChild(document.createTextNode(` · norm ${f.norm_pr_auc.toFixed(3)}`));
    if (!f.on_disk) c.title = 'Planned but not trained yet.';
    chips.appendChild(c);
  });
  if (!row.per_fold.length) chips.appendChild(h('span', 'fold-chip missing', 'no folds yet'));
  inner.appendChild(chips);
}

function detailItem(label, value) {
  const d = h('div');
  d.appendChild(h('div', 'stat-label', label));
  d.appendChild(h('div', 'detail-value', value == null || value === '' ? '—' : String(value)));
  return d;
}

/* =================================================================== TRAINING */
/* What is on the GPU right now.
 *
 * Reads only what training already writes to disk — history.csv per epoch,
 * test_metrics.json when a fold ends — so it works for a sweep started from a
 * terminal just as well as one launched from here. Both of the long sweeps
 * this project has run were started from a terminal.
 *
 * Per experiment, top to bottom: a status line in words, the four numbers you
 * act on, one bar for the whole sweep, the live validation curve of the fold
 * in flight, then every fold as a tile colored by where it stands. */
function renderTraining() {
  const body = $('#trainingBody');
  body.innerHTML = '';
  const active = [...(S.inv.training_now || [])];

  // Newest activity first, so a second experiment never shoves the live one down.
  active.sort((a, b) => {
    const ta = a.updated ? Date.parse(a.updated) : 0;
    const tb = b.updated ? Date.parse(b.updated) : 0;
    return tb - ta;
  });

  if (!active.length) {
    body.appendChild(emptyState('Nothing training right now',
      'Train one fold to check a setting works, or start an ablation sweep '
      + 'for the full matrix overnight. Finished sweeps land on the Runs page.'));
    const q = h('div', 'quick');
    q.style.marginTop = '16px';
    q.appendChild(quickButton('train-cache', 'Build cache', 'Pool datasets for training.'));
    q.appendChild(quickButton('train-train', 'Train one fold', 'One setting, one held-out run.'));
    q.appendChild(quickButton('train-ablate', 'Ablation sweep', 'The full matrix, overnight.'));
    body.appendChild(q);
    return;
  }
  active.forEach((t) => body.appendChild(trainCard(t)));
}

/** One experiment's monitor card. */
function trainCard(t) {
  const c = t.counts;
  const live = c.running;
  const stateWord = live ? 'training now' : c.stalled ? 'stalled' : 'queued';

  const card = h('section', 'card train-run');
  const head = h('div', 'train-head');
  const idBox = h('div', 'train-id');
  const title = h('h2', 'train-title', t.experiment);
  title.appendChild(h('span',
    `train-state${live ? ' live' : ''}${!live && c.stalled ? ' stall' : ''}`, stateWord));
  idBox.appendChild(title);
  idBox.appendChild(h('div', 'train-path', t.path));
  head.appendChild(idBox);
  const upd = t.updated ? Date.parse(t.updated) : NaN;
  if (!Number.isNaN(upd)) {
    head.appendChild(h('span', 'train-updated', `updated ${fmtAgo(upd / 1000)}`));
  }
  card.appendChild(head);

  // The four numbers you act on: how far along, how long left, what pace,
  // and anything that has stopped moving.
  const stats = h('div', 'train-stats');
  stats.appendChild(trainStat(
    'Folds done', `${c.done}/${t.folds_total}`,
    `${live} running · ${c.pending} queued`
    + (c.stalled ? ` · ${c.stalled} stopped` : '')));
  stats.appendChild(trainStat(
    'Time left',
    t.seconds_remaining != null
      ? (t.seconds_remaining >= 5400
        ? `~${Math.round(t.seconds_remaining / 3600)}h`
        : `~${fmtDur(t.seconds_remaining)}`)
      : '—',
    t.seconds_per_fold != null
      ? `at ${fmtDur(t.seconds_per_fold)} a fold`
      : 'no finished folds to time yet'));
  stats.appendChild(trainStat(
    'In flight', live ? String(live) : '—',
    live ? (t.in_flight[0] ? `holding out ${t.in_flight[0].fold}` : '')
      : (c.stalled ? 'nothing has moved recently' : 'not started yet')));
  stats.appendChild(trainStat(
    'Arms', String(t.arms.length), t.arms.join(', ') || '—'));
  card.appendChild(stats);

  const pct = t.folds_total ? Math.round((100 * c.done) / t.folds_total) : 0;
  const meter = h('div', 'meter');
  const fill = h('div', 'meter-fill');
  fill.style.width = `${pct}%`;
  meter.appendChild(fill);
  card.appendChild(meter);

  // The fold actually in flight: its own epoch progress plus the validation
  // curve, which is the difference between "working" and "working well".
  t.in_flight.forEach((f) => {
    const box = h('div', 'train-fold-live');
    const label = h('div', 'card-sub');
    const best = f.best_val_pr_auc == null ? '—' : f.best_val_pr_auc.toFixed(3);
    label.textContent = `Holding out ${f.fold} · epoch ${f.epochs_done}`
      + (f.epochs_planned ? ` of ${f.epochs_planned}` : '')
      + ` · best validation PR-AUC so far ${best}`
      + (f.seconds_since_epoch != null
        ? ` · last epoch ${fmtDur(f.seconds_since_epoch)} ago` : '');
    box.appendChild(label);
    if (f.epochs_planned) {
      const bar = h('div', 'epoch-bar');
      const efill = h('div', 'epoch-bar-fill');
      efill.style.width =
        `${Math.min(100, Math.round(100 * f.epochs_done / f.epochs_planned))}%`;
      bar.appendChild(efill);
      box.appendChild(bar);
    }
    const pts = (f.curve || []).filter((r) => typeof r.val_pr_auc === 'number');
    if (pts.length > 1) {
      box.appendChild(window.Charts.lineChart({
        x: pts.map((r) => r.epoch),
        xLabel: 'epoch',
        series: [
          { name: 'val PR-AUC', values: pts.map((r) => r.val_pr_auc) },
          { name: 'val loss', values: pts.map((r) => r.val_loss) },
        ],
        caption: 'How well this fold scores on data held back from its own training, '
               + 'after each pass over the data. A curve that has gone flat means the '
               + 'fold is about to stop early.',
      }));
    }
    card.appendChild(box);
  });

  // Every fold as a tile: fill = score, color = status. The whole story of
  // the sweep in one glance — which recordings were hard, where it stopped.
  const grid = h('div', 'fold-grid');
  t.folds.forEach((f) => {
    const tile = h('button', `fold-tile fs-${f.status}`);
    tile.title = f.status === 'done'
      ? `${f.fold}: held-out PR-AUC ${fmtScore(f.test_pr_auc)}`
      : f.status === 'running' ? `${f.fold}: epoch ${f.epochs_done} of ${f.epochs_planned ?? '?'}`
      : f.status === 'stalled' ? `${f.fold}: stopped partway through`
      : `${f.fold}: not started yet`;
    tile.appendChild(h('span', 'fold-name', f.fold));
    const foot = h('span', 'fold-foot');
    if (f.status === 'done') foot.textContent = fmtScore(f.test_pr_auc);
    else if (f.status === 'running') foot.textContent = `ep ${f.epochs_done}`;
    else if (f.status === 'stalled') foot.textContent = 'stopped';
    else foot.textContent = 'queued';
    tile.appendChild(foot);
    grid.appendChild(tile);
  });
  card.appendChild(grid);
  // The tiles are colored, so say what each color means right under them.
  const lg = h('div', 'legend train-legend');
  [['fs-done', 'finished'], ['fs-running', 'running'],
   ['fs-stalled', 'stopped partway'], ['fs-pending', 'not started']]
    .forEach(([cls, word]) => {
      const it = h('span', 'legend-item');
      it.appendChild(h('span', `legend-swatch ${cls}`));
      it.appendChild(document.createTextNode(word));
      lg.appendChild(it);
    });
  card.appendChild(lg);
  return card;
}

function trainStat(label, value, sub) {
  const d = h('div', 'train-stat');
  d.appendChild(h('div', 'stat-label', label));
  d.appendChild(h('div', 'train-stat-value', value));
  d.appendChild(h('div', 'stat-sub', sub || ''));
  return d;
}

/* =================================================================== DATA */
function renderData() {
  $$('#dataTabs .tab').forEach((t) => {
    t.classList.toggle('is-active', t.dataset.tab === S.dataTab);
    if (!t.dataset.wired) {
      t.dataset.wired = '1';
      t.onclick = () => { S.dataTab = t.dataset.tab; renderData(); };
    }
  });
  $$('.tab-panel').forEach((p) => p.classList.toggle('is-active', p.id === `tab-${S.dataTab}`));
  if (S.dataTab === 'recordings') renderRecordings();
  if (S.dataTab === 'labels') renderLabels();
  if (S.dataTab === 'datasets') renderDatasets();
}

function emptyState(title, body) {
  const e = h('div', 'empty');
  e.appendChild(h('strong', null, title));
  e.appendChild(h('div', null, body));
  return e;
}

function table(headers) {
  const wrap = h('div', 'table-wrap');
  const t = h('table');
  const thead = h('thead');
  const tr = h('tr');
  headers.forEach((head) => {
    const th = h('th', head.num ? 'num' : '', head.label);
    if (head.width) th.style.width = head.width;
    tr.appendChild(th);
  });
  thead.appendChild(tr);
  t.appendChild(thead);
  const tbody = h('tbody');
  t.appendChild(tbody);
  wrap.appendChild(t);
  return { wrap, tbody, cols: headers.length };
}

/** Expandable row: owns the detail <tr>, the caret glyph, and the open-set entry.
 *
 * `S.openRows` is keyed by path/name rather than row index so a row survives a
 * re-render — the poll rebuilds these tables whenever the inventory moves.
 * `fill` runs at most once per built row.
 */
function expandable(tbody, tr, key, fill, caret) {
  const detail = h('tr', 'row-detail');
  const td = h('td');
  td.colSpan = 99;
  const inner = h('div', 'row-detail-inner');
  td.appendChild(inner);
  detail.appendChild(td);
  let filled = false;

  const apply = (open) => {
    detail.hidden = !open;
    tr.classList.toggle('is-open', open);
    if (caret) caret.textContent = open ? '▾' : '▸';
    if (open) {
      S.openRows.add(key);
      if (!filled) { filled = true; fill(inner); }
    } else S.openRows.delete(key);
  };
  const toggle = () => apply(detail.hidden);
  apply(S.openRows.has(key));

  if (caret) caret.onclick = (e) => { e.stopPropagation(); toggle(); };
  tbody.appendChild(tr);
  tbody.appendChild(detail);
  return toggle;
}

function hint(text) {
  const d = h('div', 'hint');
  d.textContent = text;
  return d;
}

function renderRecordings() {
  const panel = $('#tab-recordings');
  panel.innerHTML = '';
  const recs = S.inv.recordings;
  if (!recs.length) {
    panel.appendChild(emptyState('No recordings yet',
      'Drop an .mcap into recordings/, or run Record to capture one.'));
    return;
  }

  const card = h('div', 'card');
  const head = h('div', 'card-head');
  head.appendChild(h('h2', null, `${recs.length} recordings · ${fmtBytes(recs.reduce((a, r) => a + r.size, 0))}`));
  head.appendChild(h('p', 'card-sub',
    'Click a row to read its index: format, duration, topics and point density. '
    + 'Labels are matched by filename, so Rename moves the label file with the '
    + 'recording and rewrites the run id inside it. Delete removes only the '
    + 'recording.'));
  card.appendChild(head);

  const { wrap, tbody } = table([
    { label: '', width: '28px' }, { label: 'Recording' }, { label: 'Size', num: true },
    { label: 'Modified', num: true }, { label: 'Labels' }, { label: 'Actions' },
  ]);

  recs.forEach((r) => {
    const tr = h('tr');
    const expTd = h('td');
    const exp = h('button', 'expander', '▸');
    expTd.appendChild(exp);
    tr.appendChild(expTd);

    const nameTd = h('td');
    const nameBox = h('div');
    nameBox.appendChild(h('div', null, r.name));
    nameBox.appendChild(h('div', 'muted mono', r.path));
    nameTd.appendChild(nameBox);
    tr.appendChild(nameTd);
    tr.appendChild(h('td', 'num', fmtBytes(r.size)));
    tr.appendChild(h('td', 'num nowrap', fmtAgo(r.mtime)));

    const labTd = h('td');
    const lab = r.labels ? S.inv.labels.find((l) => l.path === r.labels) : null;
    if (lab) {
      labTd.appendChild(h('span', 'pill rock', `${lab.rock_count} rocks`));
    } else {
      labTd.appendChild(h('span', 'muted', 'unlabeled'));
    }
    tr.appendChild(labTd);

    const actTd = h('td');
    const acts = h('div', 'row-actions');
    [['inspect', 'Inspect', { mcap: r.path }],
     ['label', 'Label', { mcap: r.path }],
     ['generate', 'Generate', { mcap: r.path, out: `datasets/${r.stem}` }],
     ['live', 'Replay', { play: r.path }],
    ].forEach(([id, label, pre]) => {
      const b = h('button', 'btn btn-sm', label);
      b.onclick = (e) => { e.stopPropagation(); openDrawer(id, pre); };
      acts.appendChild(b);
    });
    // Renaming a recording carries its labels along — see inventory._target.
    const keep = itemControls({
      kind: 'recording', name: r.stem, path: r.path,
      warn: `${fmtBytes(r.size)} goes for good; you cannot re-label or `
          + `re-generate from it afterwards.`
          + (r.labels ? ' Its label file stays behind.' : ''),
    }, nameBox);
    keep.triggers.forEach((b) => acts.appendChild(b));
    keep.panels.forEach((p) => nameTd.appendChild(p));
    actTd.appendChild(acts);
    tr.appendChild(actTd);

    const toggle = expandable(tbody, tr, `rec:${r.path}`, (inner) => {
      inner.appendChild(h('div', 'muted', 'reading index…'));
      api(`/api/recording?path=${encodeURIComponent(r.path)}`).then((info) => {
        inner.innerHTML = '';
        if (!info.ok) {
          inner.appendChild(h('div', 'status status-bad', `unreadable: ${info.error}`));
          if (info.hint) inner.appendChild(hint(info.hint));
          const b = h('button', 'btn btn-sm', 'Open Trim to salvage it');
          b.style.marginTop = '10px';
          b.onclick = () => openDrawer('trim', { mcap: r.path, out: `recordings/${r.stem}.fixed.mcap`, all_topics: true });
          inner.appendChild(b);
          return;
        }
        const grid = h('div', 'detail-grid');
        grid.appendChild(detailItem('Format', info.format));
        grid.appendChild(detailItem('Duration', `${info.duration_s.toFixed(1)} s`));
        grid.appendChild(detailItem('Messages', info.messages.toLocaleString()));
        grid.appendChild(detailItem('Recorded', (info.start || '').replace('T', ' ').replace('+00:00', ' UTC')));
        if (info.points_per_frame != null) {
          grid.appendChild(detailItem('Points / frame', info.points_per_frame.toLocaleString()));
          grid.appendChild(detailItem('Reflectivity', info.reflectivity ? `yes (peak ${info.reflectivity_peak})` : 'no'));
          grid.appendChild(detailItem('Poses', info.poses ? 'yes' : 'NO — SLAM never locked'));
        }
        inner.appendChild(grid);

        if (info.topics.length) {
          const tw = h('details');
          tw.style.marginTop = '12px';
          tw.appendChild(h('summary', null, `${info.topics.length} topics`));
          const tt = table([{ label: 'Topic' }, { label: 'Schema' }, { label: 'Messages', num: true }]);
          tt.wrap.style.marginTop = '8px';
          info.topics.forEach((tp) => {
            const row = h('tr');
            row.appendChild(h('td', 'mono', tp.topic));
            row.appendChild(h('td', 'muted mono', tp.schema));
            row.appendChild(h('td', 'num', tp.messages.toLocaleString()));
            tt.tbody.appendChild(row);
          });
          tw.appendChild(tt.wrap);
          inner.appendChild(tw);
        }
        if (info.pose_hint) inner.appendChild(hint(info.pose_hint));
      }).catch((e) => { inner.innerHTML = ''; inner.appendChild(h('div', 'status status-bad', e.message)); });
    }, exp);
    nameTd.style.cursor = 'pointer';
    nameTd.onclick = toggle;
  });

  card.appendChild(wrap);
  panel.appendChild(card);
}

function renderLabels() {
  const panel = $('#tab-labels');
  panel.innerHTML = '';
  const labs = S.inv.labels;
  if (!labs.length) {
    panel.appendChild(emptyState('No label files yet',
      'Run Label on a recording — labels auto-save to labels/<recording>.labels.json.'));
    return;
  }
  const card = h('div', 'card');
  const head = h('div', 'card-head');
  head.appendChild(h('h2', null, `${labs.length} label files · ${labs.reduce((a, l) => a + l.rock_count, 0)} rocks`));
  head.appendChild(h('p', 'card-sub',
    'Labels are tied to the recording they were made on by filename, so Rename '
    + 'moves both. Drift check verifies that odometry held before you generate a '
    + 'dataset from them.'));
  card.appendChild(head);

  const { wrap, tbody } = table([
    { label: 'Run' }, { label: 'Rocks', num: true }, { label: 'Shapes' },
    { label: 'Training bounds' },
    { label: 'Recording' }, { label: 'Modified', num: true }, { label: 'Actions' },
  ]);
  labs.forEach((l) => {
    const tr = h('tr');
    const runTd = h('td');
    const runBox = h('div');
    runBox.appendChild(h('div', null, l.run_id));
    if (l.stem !== l.run_id) runBox.appendChild(h('div', 'muted mono', l.name));
    runTd.appendChild(runBox);
    tr.appendChild(runTd);
    tr.appendChild(h('td', 'num', String(l.rock_count)));
    const shapes = h('td');
    Object.entries(l.shapes).forEach(([k, v]) => {
      shapes.appendChild(h('span', 'pill', `${v} ${k}`));
      shapes.appendChild(document.createTextNode(' '));
    });
    tr.appendChild(shapes);
    // Which volume Generate is allowed to train on: the arena ring bounds the
    // floor plan, the labeler's z clip bounds the height. Missing either one
    // means that direction is left to the crop box, which is worth seeing.
    const bounds = h('td');
    bounds.appendChild(h('span', l.arena_vertices ? 'pill ok' : 'pill warn',
      l.arena_vertices ? `arena ${l.arena_vertices} pts` : 'no arena'));
    bounds.appendChild(document.createTextNode(' '));
    bounds.appendChild(h('span', l.z_band ? 'pill ok' : 'pill warn',
      l.z_band ? `z ${l.z_band[0].toFixed(2)}…${l.z_band[1].toFixed(2)} m` : 'full height'));
    tr.appendChild(bounds);
    tr.appendChild(h('td', 'mono muted', l.mcap_file || '—'));
    tr.appendChild(h('td', 'num nowrap', fmtAgo(l.mtime)));
    const act = h('td');
    const acts = h('div', 'row-actions');
    const rec = S.inv.recordings.find((r) => r.name === l.mcap_file)
      || S.inv.recordings.find((r) => r.stem === l.run_id);
    const mcap = rec ? rec.path : '';
    [['label', 'Edit', { mcap, labels: l.path }],
     ['driftcheck', 'Drift check', { mcap, labels: l.path, rock_id: l.rock_ids[0] || 1 }],
     ['generate', 'Generate', { mcap, labels: l.path, out: `datasets/${l.run_id}` }],
    ].forEach(([id, label, pre]) => {
      const b = h('button', 'btn btn-sm', label);
      b.onclick = () => openDrawer(id, pre);
      acts.appendChild(b);
    });
    const keep = itemControls({
      kind: 'labels', name: l.stem, path: l.path,
      warn: `${l.rock_count} labeled rocks go for good.`
          + (rec ? ' The recording they were made on stays.' : ''),
    }, runBox);
    keep.triggers.forEach((b) => acts.appendChild(b));
    keep.panels.forEach((p) => runTd.appendChild(p));
    act.appendChild(acts);
    tr.appendChild(act);
    tbody.appendChild(tr);
  });
  card.appendChild(wrap);
  panel.appendChild(card);
}

/* --------------------------------------------------------- housekeeping */
/** The extension the server owns; the user only ever edits the stem. */
const NAME_SUFFIX = { dataset: '', recording: '.mcap', labels: '.labels.json' };

/** Rename + Delete for one item in the Data view, used by all three tabs.
 *
 * Returns `{ triggers, panels }` to append: the triggers go wherever that tab
 * keeps its buttons, the panels next to `shown` — the heading or name cell they
 * take the place of while open. All three swap with `hidden` rather than being
 * built and torn down, which keeps them mutually exclusive and stops the row
 * from reflowing as you move between them.
 *
 * `item` is `{ kind, name, path, warn }`: `name` is the stem being edited (never
 * the extension), `path` is what the server is told, and `warn` is the sentence
 * the delete confirmation shows about what will be left behind.
 *
 * Neither action moves any total, so `invSignature` cannot see them and the poll
 * would keep rendering the old listing until something else in the project
 * changed. Clearing `S.invSig` forces the next refresh to rebuild.
 */
function itemControls(item, shown) {
  const suffix = NAME_SUFFIX[item.kind];
  const rename = h('div', 'rename');
  const confirmRow = h('div', 'rename confirm');
  const panels = [rename, confirmRow];
  // These sit inside a cell that expands its row on click.
  panels.forEach((p) => { p.hidden = true; p.onclick = (e) => e.stopPropagation(); });

  const show = (panel) => {
    panels.forEach((p) => { p.hidden = p !== panel; });
    shown.hidden = Boolean(panel);
  };
  const done = async (msg) => {
    S.invSig = null;
    await refreshState();
    toast(msg);
  };

  // ---- rename
  const input = h('input', 'input rename-input');
  input.value = item.name;
  input.setAttribute('aria-label', `New name for ${item.name}`);
  const save = h('button', 'btn btn-sm btn-primary', 'Save');
  rename.appendChild(input);
  if (suffix) rename.appendChild(h('span', 'muted mono', suffix));
  rename.appendChild(save);
  rename.appendChild(button('btn btn-sm btn-ghost', 'Cancel', () => show(null)));

  save.onclick = async () => {
    const name = input.value.trim();
    if (!name || name === item.name) { show(null); return; }
    save.disabled = true;
    try {
      const r = await post('/api/rename', { path: item.path, name });
      await done(r.renamed.length > 1
        ? `Renamed to ${r.name} (${r.renamed.length} files).`
        : `Renamed to ${r.name}.`);
    } catch (e) {
      toast(writeError(e), 'err');
      input.focus();
    } finally {
      save.disabled = false;
    }
  };
  input.onkeydown = (e) => {
    if (e.key === 'Enter') { e.preventDefault(); save.onclick(); }
    if (e.key === 'Escape') { e.preventDefault(); show(null); }
  };

  // ---- delete, behind a confirmation that names what goes and what stays
  const del = h('button', 'btn btn-sm btn-danger', 'Delete permanently');
  confirmRow.appendChild(h('span', null, `Delete ${item.name}${suffix}? ${item.warn}`));
  confirmRow.appendChild(del);
  confirmRow.appendChild(button('btn btn-sm btn-ghost', 'Keep it', () => show(null)));

  del.onclick = async () => {
    del.disabled = true;
    try {
      const r = await post('/api/delete', { path: item.path });
      await done(`Deleted ${item.name}${suffix} — ${fmtBytes(r.freed)} freed.`);
    } catch (e) {
      toast(writeError(e), 'err');
    } finally {
      del.disabled = false;
    }
  };

  const triggers = [
    button('btn btn-sm rename-btn', 'Rename', () => {
      show(rename);
      input.value = item.name;
      input.focus();
      if (input.select) input.select();
    }),
    button('btn btn-sm delete-btn', 'Delete', () => show(confirmRow)),
  ];
  return { triggers, panels };
}

function button(cls, label, onclick) {
  const b = h('button', cls, label);
  b.onclick = (e) => { if (e) e.stopPropagation(); onclick(e); };
  return b;
}

/** Flask's own words for a route it does not have, which is exactly what a
 *  dashboard server older than this page answers with — static files are re-read
 *  on every refresh, but endpoints only appear when the process restarts. Saying
 *  that beats "check your spelling" for a button the user just clicked. */
function writeError(e) {
  return /requested URL was not found/i.test(e.message)
    ? 'This dashboard server predates Rename/Delete — restart `rocklabel dash` '
      + 'to pick them up. Nothing was changed.'
    : e.message;
}

function renderDatasets() {
  const panel = $('#tab-datasets');
  panel.innerHTML = '';
  const dss = S.inv.datasets;
  if (!dss.length) {
    panel.appendChild(emptyState('No datasets yet',
      'Run Generate on a labeled recording to write one.'));
    return;
  }
  dss.forEach((d) => {
    const card = h('div', 'card');
    const head = h('div', 'card-head');
    const title = h('div');
    title.style.cssText = 'display:flex; align-items:center; gap:10px; flex-wrap:wrap;';
    title.appendChild(h('h2', null, d.name));
    if (d.has_manifest) title.appendChild(h('span', 'pill', `config ${d.config_hash}`));
    else title.appendChild(h('span', 'status status-warn', 'no manifest'));
    title.appendChild(h('span', 'pill', fmtBytes(d.size)));
    const keep = itemControls({
      kind: 'dataset', name: d.name, path: d.path,
      warn: `${fmtBytes(d.size)} in ${d.files.toLocaleString()} files goes for good. `
          + 'A training cache built from it keeps its own copy.',
    }, title);
    keep.triggers.forEach((b) => title.appendChild(b));
    head.appendChild(title);
    keep.panels.forEach((p) => head.appendChild(p));
    head.appendChild(h('p', 'card-sub',
      d.has_manifest
        ? `${d.runs.length} run${d.runs.length === 1 ? '' : 's'} · ${d.samples.toLocaleString()} format-A samples · ${d.bev_frames.toLocaleString()} BEV frames`
        : 'This directory has no manifest.json — it was not written by Generate, or the run was interrupted.'));
    card.appendChild(head);

    if (d.samples > 0) {
      card.appendChild(window.Charts.proportionBar([
        { label: 'rock samples', value: d.rock_samples, color: window.Charts.seriesColor(1) },
        { label: 'clear samples', value: d.clear_samples, color: window.Charts.seriesColor(0) },
      ], { caption: `Class balance across the whole dataset. The classifiers handle this imbalance `
                  + `with class-weighted BCE — read PR-AUC and F1, never bare accuracy.` }));
    }

    if (d.runs.length) {
      const { wrap, tbody } = table([
        { label: 'Run' }, { label: 'Frames', num: true }, { label: 'Samples', num: true },
        { label: 'Rock', num: true }, { label: 'Rock share', num: true },
        { label: 'Rocks labeled', num: true }, { label: 'Actions' },
      ]);
      d.runs.forEach((r) => {
        const tr = h('tr');
        tr.appendChild(h('td', null, r.run_id));
        tr.appendChild(h('td', 'num', r.frames.toLocaleString()));
        tr.appendChild(h('td', 'num', r.samples.toLocaleString()));
        tr.appendChild(h('td', 'num', r.rock.toLocaleString()));
        const share = r.samples ? (r.rock / r.samples) * 100 : 0;
        const shareTd = h('td', 'num', `${share.toFixed(1)}%`);
        if (r.rock === 0) {
          shareTd.textContent = '0% ⚠';
          shareTd.title = 'Zero rock samples — label/frame misalignment. Run Drift check.';
          shareTd.style.color = 'var(--critical)';
        }
        tr.appendChild(shareTd);
        tr.appendChild(h('td', 'num', String(r.rock_count)));
        const act = h('td');
        const b = h('button', 'btn btn-sm', 'Preview');
        b.onclick = () => openDrawer('preview', { out_pos: d.path, run: r.run_id });
        act.appendChild(b);
        tr.appendChild(act);
        tbody.appendChild(tr);
      });
      card.appendChild(wrap);
    }

    const acts = h('div', 'row-actions');
    acts.style.marginTop = '14px';
    [['preview', 'Preview frames', { out_pos: d.path }],
     ['train-cache', 'Add to training cache', { datasets: d.path }],
    ].forEach(([id, label, pre]) => {
      const b = h('button', 'btn btn-sm', label);
      b.onclick = () => openDrawer(id, pre);
      acts.appendChild(b);
    });
    card.appendChild(acts);
    panel.appendChild(card);
  });
}

/* =================================================================== JOBS */
function renderJobs() {
  const list = $('#jobList');
  list.innerHTML = '';
  if (!S.jobs.length) {
    list.appendChild(h('li', 'muted', 'Nothing launched yet.'));
  }
  S.jobs.forEach((j) => {
    const li = h('li');
    li.classList.toggle('is-active', j.id === S.activeJob);
    const top = h('div', 'job-row-top');
    top.appendChild(h('span', 'job-title', j.title));
    top.appendChild(h('span', `status status-${j.status}`, j.status));
    li.appendChild(top);
    li.appendChild(h('div', 'job-meta', `${j.id} · ${fmtDur(j.elapsed)} · ${fmtAgo(j.started)}`));
    li.onclick = () => selectJob(j.id);
    list.appendChild(li);
  });

  const running = S.jobs.filter((j) => j.status === 'running').length;
  const badge = $('#jobsBadge');
  badge.hidden = running === 0;
  badge.textContent = String(running);

  const job = S.jobs.find((j) => j.id === S.activeJob);
  $('#jobLogTitle').textContent = job ? `${job.title} · ${job.id}` : 'No job selected';
  $('#jobLogCmd').textContent = job ? job.command_line : '';
  $('#jobStop').hidden = !(job && job.status === 'running');
  // Rerun and Stop are the same slot: a job is either live (stop it) or over
  // (run it again). Rerunning a job while its own copy still holds the sensor
  // port or a viewer window is never what you meant.
  $('#jobRerun').hidden = !(job && job.status !== 'running');
}

function selectJob(id) {
  if (S.activeJob === id) return;
  S.activeJob = id;
  S.jobCursor = 0;
  S.follow = true;
  $('#jobLog').textContent = '';
  renderJobs();
  pumpJob();
}

/** Run a finished job's command line again and follow the new job's log. */
async function rerunJob(id) {
  const btn = $('#jobRerun');
  btn.disabled = true;
  try {
    const r = await post(`/api/jobs/${id}/rerun`);
    await refreshJobs();
    selectJob(r.job.id);
    toast(`Started ${r.job.title} again (${r.job.id}).`);
  } catch (e) {
    toast(e.message, 'err');
  } finally {
    btn.disabled = false;
  }
}

async function stopJob(id) {
  try {
    await post(`/api/jobs/${id}/stop`);
    toast('Stop signal sent.');
  } catch (e) { toast(e.message, 'err'); }
  refreshJobs();
}

function logClass(line) {
  const l = line.toLowerCase();
  if (line.startsWith('[dashboard] $')) return 'l-cmd';
  if (l.includes('error') || l.includes('traceback') || l.includes('failed')
      || l.includes('exited with code 1')) return 'l-err';
  if (l.includes('warning') || l.includes('warn:')) return 'l-warn';
  if (l.includes('exited with code 0') || l.includes('saved')) return 'l-ok';
  return '';
}

async function pumpJob() {
  const id = S.activeJob;
  if (!id) return;
  let data;
  try {
    data = await api(`/api/jobs/${id}?since=${S.jobCursor}`);
  } catch { return; }
  if (S.activeJob !== id) return;

  const pre = $('#jobLog');
  if (data.dropped) {
    pre.appendChild(h('div', 'l-warn',
      `… ${data.dropped} earlier lines dropped (full log in .dashboard/logs/${id}.log)`));
  }
  const atBottom = pre.scrollHeight - pre.scrollTop - pre.clientHeight < 40;
  data.lines.forEach((line) => {
    pre.appendChild(h('div', logClass(line), line));
  });
  S.jobCursor = data.cursor;
  if (S.follow && (atBottom || data.lines.length)) pre.scrollTop = pre.scrollHeight;
  renderJobs();
}

/* =================================================================== LIVE */
let sensorTimer = null;

function renderLive() {
  const box = $('#liveActions');
  if (!box.dataset.built) {
    const pre = { z_min: -1.5, z_max: -0.5, max_range: 8, source: 'udp' };
    box.appendChild(quickButton('live', 'Live view', 'Sensor stream, no recording.', pre));
    box.appendChild(quickButton('record', 'Record now', 'Capture straight to disk.', pre));
    const best = S.inv.checkpoints.find((c) => c.name.endsWith('best.pt'));
    box.appendChild(quickButton('live', 'Live + model', 'Score the live cloud as you sweep.',
      { ...pre, model: best ? best.path : '', color_mode: 'model' }));
    box.appendChild(quickButton('live', 'Replay a recording', 'Same pipeline, from a file.',
      { ...pre, play: (S.inv.recordings[0] || {}).path || '' }));
    box.dataset.built = '1';
    $('#liveHint').innerHTML =
      'The handheld presets assume the sensor sits about <b>1&nbsp;m above the floor</b> ' +
      '(<code>--z-min -1.5 --z-max -0.5 --max-range 8</code>). Adjust them in the drawer ' +
      'if the rig is mounted differently.';
  }
  refreshSensor();
  if (!sensorTimer) sensorTimer = setInterval(refreshSensor, 5000);
  renderControlPanel();
  renderLiveJobs();
}

/* The live control panel of whichever capture/viewer is running, embedded.
 *
 * `panel_url` appears on the job only once the child process has announced it
 * is serving, so there is no window where this frames a dead port.
 *
 * The one rule here: never reassign src for a URL that is already loaded. This
 * runs on every 5 s poll, and re-setting src reloads the page inside the frame
 * — which would throw away the user's scroll position and reset any control
 * they were mid-drag on, twelve times a minute. */
function renderControlPanel() {
  const card = $('#panelCard');
  const frame = $('#panelFrame');
  const job = S.jobs.find((j) => j.status === 'running' && j.panel_url);

  if (!job) {
    card.hidden = true;
    if (frame.dataset.src) {          // release the dead panel
      frame.removeAttribute('src');
      delete frame.dataset.src;
    }
    return;
  }

  card.hidden = false;
  $('#panelTitle').textContent = `${job.title} · controls`;
  $('#panelSub').textContent =
    `${job.id} — the 3D window is on your desktop; everything that steers it is here.`;
  if (frame.dataset.src !== job.panel_url) {
    frame.dataset.src = job.panel_url;
    frame.src = job.panel_url;
  }
  if (!card.dataset.wired) {
    card.dataset.wired = '1';
    $('#panelPop').onclick = () => {
      if (frame.dataset.src) window.open(frame.dataset.src, '_blank', 'noopener');
    };
    $('#panelReload').onclick = () => { frame.src = frame.dataset.src; };
  }
}

async function refreshSensor() {
  if (S.view !== 'live' || document.hidden) return;
  const body = $('#sensorBody');
  let s;
  try {
    s = await api('/api/sensor');
  } catch (e) {
    body.innerHTML = '';
    body.appendChild(h('div', 'muted', `probe failed: ${e.message}`));
    return;
  }

  body.innerHTML = '';
  const headLine = h('div', 'sensor-headline');
  const glyph = { streaming: '◉', idle: '◌', busy: '◑', offline: '✕', unknown: '?' }[s.state];
  headLine.appendChild(h('div', `sensor-dot ${s.state}`, glyph));
  const meta = h('div');
  meta.appendChild(h('div', 'sensor-state', s.label));
  meta.appendChild(h('div', 'muted', `${s.sensor_ip} · udp/${s.udp_port}`));
  headLine.appendChild(meta);
  body.appendChild(headLine);

  const checks = [
    { name: 'Reachable (ICMP)',
      ok: s.ping.reachable,
      detail: s.ping.detail + (s.ping.rtt_ms != null ? ` · ${s.ping.rtt_ms} ms` : '') },
    { name: 'Streaming Compact data',
      ok: s.listen.streaming,
      detail: s.listen.detail },
    { name: 'Host on the sensor subnet',
      ok: s.same_subnet,
      detail: s.interfaces.length
        ? s.interfaces.map((i) => `${i.name} ${i.address}`).join(' · ')
        : 'no non-loopback interfaces found' },
  ];
  checks.forEach((c) => {
    const row = h('div', 'check-row');
    const icon = h('div', 'check-icon', c.ok === true ? '✓' : c.ok === false ? '✕' : '–');
    icon.style.color = c.ok === true ? 'var(--good)'
      : c.ok === false ? 'var(--critical)' : 'var(--text-muted)';
    row.appendChild(icon);
    const txt = h('div');
    txt.appendChild(h('div', 'check-name', c.name));
    txt.appendChild(h('div', 'check-detail', c.detail));
    row.appendChild(txt);
    body.appendChild(row);
  });

  if (s.state === 'offline') {
    body.appendChild(hint('The sensor is not answering. Check power and the Ethernet link, ' +
      'then confirm this machine has an address on the sensor\'s subnet — that is the usual culprit.'));
  } else if (s.state === 'idle') {
    body.appendChild(hint('Powered and reachable, but nothing is arriving on the Compact port. ' +
      'Check the SOPAS output configuration: destination host and port must point here.'));
  } else if (s.state === 'busy') {
    body.appendChild(hint('A live job owns the UDP port right now, so the streaming check is ' +
      'skipped — read that job\'s throughput below instead.'));
  }

  const fix = s.network_fix;
  if (fix && fix.suggested) {
    body.appendChild(netFixBlock(fix));
  } else if (fix && fix.link_down) {
    // Addressing is right, the cable is not: no script would help here.
    body.appendChild(hint(`No carrier on ${fix.iface} — its addresses are set up correctly, ` +
      'so this is the cable or the sensor\'s power, not the network configuration.'));
  }
}

/* The wired NIC is misconfigured and no data is arriving: show what is wrong
 * and the script that fixes it. Deliberately copy-to-clipboard rather than a
 * "Fix it" button — every step needs root, and `ip addr flush` on the wrong
 * interface is how you drop your ssh session. */
function netFixBlock(fix) {
  const box = h('div', 'netfix');
  const head = h('div', 'netfix-head');
  head.appendChild(h('div', 'netfix-title',
    `Wired link to the sensor looks misconfigured${fix.iface ? ` (${fix.iface})` : ''}`));
  const copy = h('button', 'btn btn-sm', 'Copy commands');
  copy.onclick = async () => {
    try {
      await navigator.clipboard.writeText(fix.script);
      toast('Repair commands copied — paste them into a terminal.');
    } catch { toast('Could not access the clipboard.', 'err'); }
  };
  head.appendChild(copy);
  box.appendChild(head);

  const why = h('ul', 'netfix-problems');
  (fix.problems || []).forEach((p) => why.appendChild(h('li', null, p)));
  if (why.children.length) box.appendChild(why);

  box.appendChild(h('div', 'netfix-lead',
    'Plugged straight into a laptop there is no DHCP on that cable, so NetworkManager ' +
    'keeps retrying and tearing the addresses back down. Take the port away from it and ' +
    'set the addresses by hand — run these in a terminal, then re-check:'));

  const pre = h('pre', 'netfix-script');
  (fix.commands || []).forEach((c) => {
    pre.appendChild(h('span', 'netfix-why', `# ${c.why}\n`));
    pre.appendChild(h('span', 'netfix-cmd', `${c.cmd}\n`));
  });
  box.appendChild(pre);

  const again = h('button', 'btn btn-sm', 'Re-check now');
  again.onclick = () => refreshSensor();
  box.appendChild(again);
  return box;
}

function renderLiveJobs() {
  const box = $('#liveJobs');
  box.innerHTML = '';
  const live = S.jobs.filter((j) => ['live', 'record'].includes(j.command_id));
  if (!live.length) {
    const e = h('div', 'empty');
    e.appendChild(h('strong', null, 'No capture or viewer running'));
    e.appendChild(h('div', null, 'Launch one above and its output shows up here.'));
    box.appendChild(e);
    return;
  }
  live.slice(0, 6).forEach((j) => {
    const row = h('div', 'check-row');
    row.style.alignItems = 'center';
    row.appendChild(h('span', `status status-${j.status}`, j.status));
    const txt = h('div');
    txt.style.flex = '1';
    txt.appendChild(h('div', 'check-name', `${j.title} · ${j.id}`));
    txt.appendChild(h('code', 'check-detail', j.command_line));
    row.appendChild(txt);
    // Every job in this list is a panel command, so a running one either has
    // its controls up or is a second away from having them. Saying which beats
    // leaving a gap where a button is about to appear.
    if (j.status === 'running') {
      if (j.panel_url) {
        const controls = h('button', 'btn btn-sm', 'Controls');
        controls.title = 'Show this job’s control panel above';
        controls.onclick = () => {
          renderControlPanel();
          const card = $('#panelCard');
          if (card.scrollIntoView) card.scrollIntoView({ behavior: 'smooth' });
        };
        row.appendChild(controls);
      } else {
        row.appendChild(h('span', 'check-detail', 'panel starting…'));
      }
    }
    const open = h('button', 'btn btn-sm', 'Open log');
    open.onclick = () => { selectJob(j.id); setView('jobs'); };
    row.appendChild(open);
    if (j.status === 'running') {
      const stop = h('button', 'btn btn-sm btn-danger', 'Stop');
      stop.onclick = () => stopJob(j.id);
      row.appendChild(stop);
    }
    box.appendChild(row);
  });
}

/* ================================================================ DRAWER */
function openDrawer(cmdId, prefill) {
  const cmd = S.catalog.commands.find((c) => c.id === cmdId);
  if (!cmd) return;
  S.drawerCmd = cmd;
  S.showAllHelp = false;

  $('#drawerEyebrow').textContent = cmd.cli;
  $('#drawerTitle').textContent = cmd.title;
  $('#drawerTagline').textContent = cmd.tagline;

  const ex = $('#drawerExplainer');
  ex.innerHTML = '';
  ex.appendChild(h('h3', null, 'What it does'));
  ex.appendChild(h('p', null, cmd.what));
  ex.appendChild(h('h3', null, 'When you reach for it'));
  ex.appendChild(h('p', null, cmd.why));
  if (cmd.notes && cmd.notes.length) {
    ex.appendChild(h('h3', null, 'Worth knowing'));
    const ul = h('ul');
    cmd.notes.forEach((nt) => ul.appendChild(h('li', null, nt)));
    ex.appendChild(ul);
  }
  if (cmd.gui) {
    ex.appendChild(hint('This opens an Open3D window on your desktop. The dashboard streams '
      + 'its console output; close the window (or press Q in it) to finish the job.'));
  }

  buildForm(cmd, prefill || {});
  $('#scrim').hidden = false;
  $('#drawer').hidden = false;
  const first = $('#runForm .input');
  if (first) first.focus();
  updatePreview();
}

function closeDrawer() {
  $('#scrim').hidden = true;
  $('#drawer').hidden = true;
  S.drawerCmd = null;
}

function sourceOptions(source) {
  if (!source || !S.inv) return null;
  const map = {
    recordings: S.inv.recordings, labels: S.inv.labels, datasets: S.inv.datasets,
    checkpoints: S.inv.checkpoints, configs: S.inv.configs, cache_runs: S.inv.cache_runs,
    caches: S.inv.caches, profiles: S.inv.profiles,
  };
  const list = map[source];
  if (!list) return null;
  // group/archived/best_of_experiment are optional — the checkpoint list sets
  // all three, the recording and dataset lists set only group.
  return list.map((x) => ({
    label: x.name,
    value: x.path,
    group: x.group || '',
    disabled: !!x.disabled,
    note: x.note || '',
    archived: !!x.archived,
    best: !!x.best_of_experiment,
  }));
}

/* Fill a <select> from sourceOptions, keeping the groups.
 *
 * The checkpoint picker was a flat alphabetical list of 354 paths, which is
 * not something anyone can choose from. Options carry the run that produced
 * them now, so they go into <optgroup>s — and the best checkpoint of each
 * experiment is lifted into a group at the top, because that is the one
 * wanted nine times out of ten. Archived runs are hidden behind a toggle:
 * they are old settings kept for the record, not candidates. */
function fillSelect(sel, opts, showArchived) {
  sel.innerHTML = '';
  const blank = h('option', null, opts.length ? 'Choose…' : 'none available');
  blank.value = '';
  sel.appendChild(blank);

  const visible = opts.filter((o) => showArchived || !o.archived);
  const mkOption = (o) => {
    const opt = h('option', null, o.note ? `${o.label} — ${o.note}` : o.label);
    opt.value = o.value;
    opt.disabled = o.disabled;
    return opt;
  };

  const best = visible.filter((o) => o.best);
  if (best.length > 1) {
    const grp = h('optgroup');
    grp.label = '★ Best of each experiment';
    best.forEach((o) => {
      const opt = mkOption(o);
      opt.textContent = `${o.group} · ${o.label}`;
      grp.appendChild(opt);
    });
    sel.appendChild(grp);
  }

  const groups = new Map();
  visible.forEach((o) => {
    if (!groups.has(o.group)) groups.set(o.group, []);
    groups.get(o.group).push(o);
  });
  groups.forEach((items, name) => {
    if (!name) { items.forEach((o) => sel.appendChild(mkOption(o))); return; }
    const grp = h('optgroup');
    grp.label = name;
    items.forEach((o) => grp.appendChild(mkOption(o)));
    sel.appendChild(grp);
  });
}

function buildForm(cmd, prefill) {
  const form = $('#runForm');
  form.innerHTML = '';

  if (cmd.presets && cmd.presets.length) {
    const box = h('div', 'presets');
    cmd.presets.forEach((p) => {
      const b = h('button', 'preset-btn');
      b.type = 'button';
      b.appendChild(document.createTextNode(p.name));
      b.appendChild(h('small', null, p.help));
      b.onclick = () => {
        Object.entries(p.values).forEach(([k, v]) => setFieldValue(k, v));
        updatePreview();
        toast(`Applied preset: ${p.name}`);
      };
      box.appendChild(b);
    });
    form.appendChild(box);
  }

  const helpToggle = h('button', 'btn btn-ghost btn-sm', 'Show all explanations');
  helpToggle.type = 'button';
  helpToggle.style.alignSelf = 'flex-start';
  helpToggle.onclick = () => {
    S.showAllHelp = !S.showAllHelp;
    helpToggle.textContent = S.showAllHelp ? 'Hide explanations' : 'Show all explanations';
    $$('.field-help', form).forEach((el) => { el.hidden = !S.showAllHelp; });
  };
  form.appendChild(helpToggle);

  const basic = cmd.params.filter((p) => !p.advanced);
  const adv = cmd.params.filter((p) => p.advanced);
  basic.forEach((p) => form.appendChild(field(p, prefill)));

  if (adv.length) {
    const details = h('details', 'advanced');
    details.appendChild(h('summary', null, `Advanced · ${adv.length} more options`));
    const body = h('div', 'advanced-body');
    adv.forEach((p) => body.appendChild(field(p, prefill)));
    details.appendChild(body);
    // Open it if a prefill touched anything inside.
    if (adv.some((p) => prefill[p.name] !== undefined)) details.open = true;
    form.appendChild(details);
  }
  form.addEventListener('input', updatePreview);
  form.addEventListener('change', updatePreview);
}

function field(p, prefill) {
  const initial = prefill[p.name] !== undefined ? prefill[p.name] : p.default;

  if (p.kind === 'bool') {
    const wrap = h('div', 'field');
    const label = h('label', 'checkbox');
    const input = h('input');
    input.type = 'checkbox';
    input.dataset.param = p.name;
    input.checked = Boolean(initial);
    label.appendChild(input);
    const txt = h('div');
    const lbl = h('div', 'field-label');
    lbl.appendChild(document.createTextNode(p.label));
    if (p.help) lbl.appendChild(helpButton(wrap));
    txt.appendChild(lbl);
    label.appendChild(txt);
    wrap.appendChild(label);
    if (p.help) wrap.appendChild(helpText(p.help));
    return wrap;
  }

  const wrap = h('div', 'field');
  const lbl = h('div', 'field-label');
  lbl.appendChild(document.createTextNode(p.label));
  if (p.required) lbl.appendChild(h('span', 'req', '*'));
  if (p.unit) lbl.appendChild(h('span', 'field-unit', `(${p.unit})`));
  if (p.help) lbl.appendChild(helpButton(wrap));
  wrap.appendChild(lbl);

  const row = h('div', 'field-row');

  if (p.kind === 'multi') {
    // A checkbox per choice, backed by a hidden comma-joined input so the
    // whole repeat/nargs pipeline (formValues, preview, presets) is unchanged.
    const store = h('input');
    store.type = 'hidden';
    store.dataset.param = p.name;
    const boxes = [];
    const group = h('div', 'multi-group');
    const selected = new Set(
      (Array.isArray(initial) ? initial : String(initial ?? '').split(','))
        .map((s) => String(s).trim()).filter(Boolean),
    );
    const sync = () => { store.value = boxes.filter((b) => b.checked).map((b) => b.value).join(', '); };
    p.choices.forEach((c) => {
      const label = h('label', 'checkbox multi-item');
      const box = h('input');
      box.type = 'checkbox';
      box.value = c;
      box.checked = selected.has(c);
      box.onchange = () => { sync(); updatePreview(); };
      boxes.push(box);
      label.appendChild(box);
      label.appendChild(h('span', null, c));
      group.appendChild(label);
    });
    sync();
    // setFieldValue writes the hidden input; the boxes have to follow it.
    store._sync = (value) => {
      const want = new Set((Array.isArray(value) ? value : String(value ?? '').split(','))
        .map((s) => String(s).trim()).filter(Boolean));
      boxes.forEach((b) => { b.checked = want.has(b.value); });
      sync();
    };
    row.appendChild(group);
    row.appendChild(store);
  } else if (p.kind === 'enum') {
    const sel = h('select', 'input');
    sel.dataset.param = p.name;
    p.choices.forEach((c) => {
      const o = h('option', null, c === '' ? '(default)' : c);
      o.value = c;
      sel.appendChild(o);
    });
    sel.value = initial != null ? String(initial) : (p.choices.includes('') ? '' : p.choices[0]);
    sel.style.maxWidth = 'none';
    row.appendChild(sel);
  } else {
    const opts = sourceOptions(p.source);
    if (opts && opts.length) {
      const sel = h('select', 'input');
      fillSelect(sel, opts, false);
      row.appendChild(sel);
      const input = textInput(p, initial);
      row.appendChild(input);
      // Only offer the toggle where there is something archived to show.
      if (opts.some((o) => o.archived)) {
        const tog = h('label', 'checkline');
        const cb = h('input');
        cb.type = 'checkbox';
        cb.onchange = () => fillSelect(sel, opts, cb.checked);
        tog.appendChild(cb);
        tog.appendChild(h('span', 'muted', 'show archived runs'));
        row.appendChild(tog);
      }
      sel.onchange = () => {
        if (!sel.value) return;
        // Repeatable fields append; single-value fields replace.
        input.value = p.repeat && input.value
          ? `${input.value}, ${sel.value}` : sel.value;
        sel.value = '';
        updatePreview();
      };
    } else {
      row.appendChild(textInput(p, initial));
    }
  }
  wrap.appendChild(row);
  if (p.help) wrap.appendChild(helpText(p.help));
  return wrap;
}

function textInput(p, initial) {
  const input = h('input', 'input');
  input.dataset.param = p.name;
  input.type = (p.kind === 'int' || p.kind === 'float') ? 'number' : 'text';
  if (p.kind === 'int') input.step = '1';
  if (p.step != null) input.step = String(p.step);
  if (p.min != null) input.min = String(p.min);
  if (p.max != null) input.max = String(p.max);
  input.placeholder = p.placeholder || (p.required ? 'required' : 'default');
  if (initial != null && initial !== '') input.value = String(initial);
  return input;
}

function helpButton(wrap) {
  const b = $('#tpl-help').content.firstElementChild.cloneNode(true);
  b.onclick = (e) => {
    e.preventDefault();
    const txt = $('.field-help', wrap);
    txt.hidden = !txt.hidden;
    b.classList.toggle('is-open', !txt.hidden);
  };
  return b;
}

function helpText(text) {
  const d = h('div', 'field-help', text);
  d.hidden = !S.showAllHelp;
  return d;
}

function setFieldValue(name, value) {
  const node = $(`[data-param="${name}"]`, $('#runForm'));
  if (!node) return;
  if (node.type === 'checkbox') node.checked = Boolean(value);
  else if (node._sync) node._sync(value);
  else node.value = value == null ? '' : String(value);
}

function formValues() {
  const values = {};
  $$('[data-param]', $('#runForm')).forEach((node) => {
    values[node.dataset.param] = node.type === 'checkbox' ? node.checked : node.value;
  });
  return values;
}

let previewTimer = null;
function updatePreview() {
  clearTimeout(previewTimer);
  previewTimer = setTimeout(async () => {
    if (!S.drawerCmd) return;
    const out = $('#cmdPreview');
    try {
      const r = await post('/api/preview', {
        command_id: S.drawerCmd.id, values: formValues(),
      });
      out.textContent = r.command_line || r.error || '—';
      out.classList.toggle('is-error', Boolean(r.error));
      $('#runBtn').disabled = Boolean(r.error);
    } catch (e) {
      out.textContent = e.message;
      out.classList.add('is-error');
    }
  }, 110);
}

async function runCommand() {
  if (!S.drawerCmd) return;
  const cmd = S.drawerCmd;
  const btn = $('#runBtn');
  btn.disabled = true;
  try {
    const r = await post('/api/run', {
      command_id: cmd.id, values: formValues(),
    });
    closeDrawer();
    await refreshJobs();
    selectJob(r.job.id);
    if (cmd.panel) {
      // The controls for this job are the point of launching it, so land on
      // them rather than on the log. Its panel takes a second to come up.
      setView('live');
      awaitPanel(r.job.id);
    } else {
      setView('jobs');
    }
    toast(`Started ${r.job.title} (${r.job.id}).`);
  } catch (e) {
    toast(e.message, 'err');
  } finally {
    btn.disabled = false;
  }
}

/* Poll hard until the new job's panel is serving, then let the 5 s loop take
 * over. Without this the embed would not appear for up to a full poll period,
 * which reads as "the button did nothing". Gives up quietly after ~20 s — the
 * job's log is where a real failure gets explained. */
async function awaitPanel(jobId, tries = 50) {
  if (tries <= 0) return;
  try {
    const job = await api(`/api/jobs/${jobId}`);
    if (job.panel_url || job.status !== 'running') {
      await refreshJobs();
      if (S.view === 'live') renderControlPanel();
      return;
    }
  } catch { /* the poll loop will catch up */ }
  setTimeout(() => awaitPanel(jobId, tries - 1), 400);
}

/* ================================================================= POLL */
/** Cheap change detector so a 5 s poll does not rebuild static tables forever.
 *  Rebuilding blows away text selections and collapses nothing useful. */
function invSignature(inv) {
  const t = inv.totals;
  return [
    t.recordings, t.recordings_bytes, t.labels, t.rocks, t.datasets, t.samples,
    t.runs, t.runs_complete, t.best_f1,
    inv.recordings.length && inv.recordings[0].mtime,
    inv.figures.length,
    // A running sweep finishes a fold every few minutes and changes nothing
    // else on the page, so without this the progress line never moves.
    t.ablation_runs_done, t.ablation_runs_total,
    (inv.training_now || []).length,
  ].join('|');
}

async function refreshState() {
  if (document.hidden) return;
  try {
    const s = await api('/api/state');
    const sig = invSignature(s.inventory);
    const changed = sig !== S.invSig;
    S.invSig = sig;
    S.inv = s.inventory;
    S.machine = s.machine;
    S.jobs = s.jobs;
    renderMachine();

    // The Training tab's badge counts experiments with unfinished work, and
    // moves whether or not that view is open.
    const tnow = s.inventory.training_now || [];
    const tb = $('#trainBadge');
    tb.hidden = tnow.length === 0;
    tb.textContent = String(tnow.length);

    // Jobs, the live sensor and training genuinely move every tick; the
    // pipeline, data and tools tables only move when a command has written
    // something. The board re-reads on entry when the signature moved underneath it.
    if (changed || ['pipeline', 'jobs', 'live', 'tools', 'training'].includes(S.view)) {
      render();
    }
    else if (S.view === 'runs' && S.board && sig !== S.boardSig) loadBoard();
    else renderJobs();
  } catch (e) { /* transient; the next tick retries */ }
}

async function refreshJobs() {
  try {
    const r = await api('/api/jobs');
    S.jobs = r.jobs;
    renderJobs();
  } catch { /* ignore */ }
}

function renderMachine() {
  const m = S.machine || {};
  const strip = $('#machineStrip');
  strip.innerHTML = '';
  const cell = (label, value, title) => {
    const d = h('div');
    d.title = title || '';
    d.appendChild(h('b', null, value));
    d.appendChild(document.createTextNode(label));
    return d;
  };
  if (m.cpu_percent != null) {
    strip.appendChild(cell('CPU', `${Math.round(m.cpu_percent)}%`, `${m.cpu_count} threads`));
  }
  if (m.memory_percent != null) {
    strip.appendChild(cell('RAM', `${Math.round(m.memory_percent)}%`,
      `${fmtBytes(m.memory_used)} of ${fmtBytes(m.memory_total)}`));
  }
  (m.gpus || []).slice(0, 1).forEach((g) => {
    strip.appendChild(cell('GPU', `${g.utilization}%`,
      `${g.name} · ${g.memory_used_mb}/${g.memory_total_mb} MB · ${g.temperature_c}°C`));
  });
  if (m.disk_free != null) strip.appendChild(cell('free', fmtBytes(m.disk_free), 'disk free'));
}

function render() {
  if (!S.inv || !S.catalog) return;
  if (S.view === 'pipeline') renderPipeline();
  if (S.view === 'tools') renderTools();
  if (S.view === 'live') renderLive();
  if (S.view === 'data') renderData();
  if (S.view === 'runs') { ensureBoard(); renderBoard(); }
  if (S.view === 'training') renderTraining();
  renderJobs();
}

/* ================================================================== INIT */
async function init() {
  $$('.nav-item').forEach((b) => { b.onclick = () => setView(b.dataset.view); });
  $('#drawerClose').onclick = closeDrawer;
  $('#scrim').onclick = closeDrawer;
  $('#runBtn').onclick = runCommand;
  $('#copyCmd').onclick = async () => {
    try {
      await navigator.clipboard.writeText($('#cmdPreview').textContent);
      toast('Command copied.');
    } catch { toast('Could not access the clipboard.', 'err'); }
  };
  $('#jobStop').onclick = () => { if (S.activeJob) stopJob(S.activeJob); };
  $('#jobRerun').onclick = () => { if (S.activeJob) rerunJob(S.activeJob); };
  $('#jobFollow').onclick = () => {
    S.follow = !S.follow;
    const b = $('#jobFollow');
    b.textContent = S.follow ? 'Following' : 'Paused';
    b.setAttribute('aria-pressed', String(S.follow));
  };
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !$('#drawer').hidden) closeDrawer();
  });

  try {
    S.catalog = await api('/api/catalog');
  } catch (e) {
    document.body.innerHTML = `<div class="empty" style="margin:60px">
      <strong>Could not load the command catalog</strong>${e.message}</div>`;
    return;
  }
  await refreshState();

  setInterval(refreshState, 5000);
  setInterval(() => {
    if (document.hidden) return;
    const job = S.jobs.find((j) => j.id === S.activeJob);
    if (job && (job.status === 'running' || S.jobCursor < job.line_count)) pumpJob();
  }, 900);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) refreshState(); });
}

init();
